SELECT m.id AS wallet_position_id, m.symbol, m.opened_at, COUNT(e.id) AS events, GROUP_CONCAT(DISTINCT e.event_type) AS event_types FROM wallet_managed_position m LEFT JOIN position_management_event e ON e.wallet_position_id = m.id WHERE m.id IN (109,110) OR m.entry_signal_id IN (SELECT signal_id FROM paper_position WHERE id IN (104,101,96,91,82,78)) GROUP BY m.id, m.symbol, m.opened_at ORDER BY m.id LIMIT 20